def gcd(a, b):
	if b == 0:
		return a
	return gcd(b, a % b)

def normalize_rational(num, den):
	if num ^ den < 0 and num > 0 or (num ^ den > 0 and num < 0):
		num = -num
		den = -den
	g = gcd(abs(num), abs(den))
	num //= g
	den //= g
	return (num, den)
